"use client";
import { ArtemisScope } from "./artemis-scope";
import View0 from "./components/crypto-markets/variants/01-price-table";
export interface ArtemisCryptoMarketsProps { className?: string;  }
export function ArtemisCryptoMarkets({ className }: ArtemisCryptoMarketsProps) {return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View0/></div></ArtemisScope>;}

"use client";
// @zeus-internal
import { AnimatePresence, motion, useInView, type Transition } from "motion/react";
import { useEffect, useId, useMemo, useRef, useState, type KeyboardEvent } from "react";
import { ArtemisDigitSwap } from "../../../foundations/digit-swap";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import { artemisCx } from "../../../lib/utils";
import { COINS, INITIAL_WATCHLIST, STABLE_VOLATILITY, TABS, TICK_COINS, TICK_MS, VOLATILITY, formatChange, formatCompact, formatPrice, type Coin, type TabValue, } from "./01-price-table/data";
import { COIN_ICONS } from "./01-price-table/icons";
type LiveCoin = Coin & {
    direction: "up" | "down" | null;
    flash: number;
};
type SortKey = "rank" | "name" | "price" | "change" | "cap" | "volume";
type Sort = {
    key: SortKey;
    dir: "ascending" | "descending";
};
const ROW_STAGGER = 0.03;
const ROW_IN: Transition = { duration: 0.35, ease: ARTEMIS_EASE_OUT };
const ROW_EXIT: Transition = { duration: 0.15, ease: "easeIn" };
const ROW_LAYOUT: Transition = { type: "spring", stiffness: 570, damping: 51 };
const STAR_SPRING: Transition = { type: "spring", stiffness: 700, damping: 35 };
const FLASH: Transition = { duration: 1.2, ease: ARTEMIS_EASE_OUT };
const SPARK: Transition = { duration: 0.9, ease: ARTEMIS_EASE_OUT };
const SPARK_DELAY = 0.2;
const TAB_INDICATOR: Transition = { type: "spring", stiffness: 170, damping: 24, mass: 1.2 };
const TAB_BUTTON = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:py-1.5 art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
const SORT_BUTTON = "art:justify-center art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:h-auto art:p-0 art:font-normal art:hover:bg-transparent art:inline-flex art:items-center art:gap-1 art:text-xs art:hover:text-foreground";
const STAR_BUTTON = "art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:text-muted-foreground art:hover:bg-primary/5 art:hover:text-foreground art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:size-8 art:rounded-full";
const STAR_PATH = "M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.123 2.123 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.123 2.123 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.122 2.122 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.122 2.122 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.122 2.122 0 0 0 1.597-1.16z";
const positive = (change: number) => change >= 0;
const changeColor = (change: number) => positive(change) ? "art:text-emerald-600 art:dark:text-emerald-400" : "art:text-red-600 art:dark:text-red-400";
function tick(coins: readonly LiveCoin[], step: number): LiveCoin[] {
    const picked = new Set<number>();
    while (picked.size < TICK_COINS)
        picked.add(Math.floor(Math.random() * coins.length));
    return coins.map((coin, index) => {
        if (!picked.has(index))
            return coin;
        const factor = 1 + (Math.random() - 0.5) * (coin.stable ? STABLE_VOLATILITY : VOLATILITY);
        return {
            ...coin,
            price: coin.price * factor,
            cap: coin.cap * factor,
            change: ((1 + coin.change / 100) * factor - 1) * 100,
            direction: factor >= 1 ? "up" : "down",
            flash: step,
        };
    });
}
function compare(a: LiveCoin, b: LiveCoin, key: SortKey): number {
    if (key === "name")
        return a.name.localeCompare(b.name);
    return a[key] - b[key];
}
function SortIcon({ active, dir }: {
    active: boolean;
    dir: Sort["dir"];
}) {
    if (!active)
        return (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevrons-up-down art:size-3.5 art:opacity-50" aria-hidden="true">
        <path d="m7 15 5 5 5-5"/>
        <path d="m7 9 5-5 5 5"/>
      </svg>);
    return dir === "ascending" ? (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-up art:size-3.5" aria-hidden="true">
      <path d="m18 15-6-6-6 6"/>
    </svg>) : (<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevron-down art:size-3.5" aria-hidden="true">
      <path d="m6 9 6 6 6-6"/>
    </svg>);
}
function SortHeader({ label, sortKey, sort, onSort, className, }: {
    label: string;
    sortKey: SortKey;
    sort: Sort;
    onSort: (key: SortKey) => void;
    className: string;
}) {
    const active = sort.key === sortKey;
    return (<th scope="col" aria-sort={active ? sort.dir : undefined} className={className}>
      <button type="button" className={artemisCx(SORT_BUTTON, active ? "art:text-foreground" : "art:text-muted-foreground", "art:rounded-full")} onClick={() => onSort(sortKey)}>
        {label}
        <SortIcon active={active} dir={sort.dir}/>
      </button>
    </th>);
}
function CoinMark({ symbol, size }: {
    symbol: string;
    size: "art:size-8" | "art:size-7";
}) {
    return (<span aria-hidden="true" className={artemisCx("art:relative art:inline-flex art:shrink-0", size)}>
      <span className="art:flex art:size-full art:items-center art:justify-center art:overflow-hidden art:rounded-full art:bg-muted art:text-foreground">
        {COIN_ICONS[symbol]}
      </span>
    </span>);
}
function SearchField({ value, onChange }: {
    value: string;
    onChange: (value: string) => void;
}) {
    const id = useId();
    const [focused, setFocused] = useState(false);
    return (<div className="art:flex art:flex-col art:gap-1.5 art:w-full art:@min-[640px]/artemis:w-72">
      <div data-state={focused ? "focused" : "idle"} className={artemisCx("art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200", focused ? "art:border-foreground/60" : "art:border-border")}>
        <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
          <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-search" aria-hidden="true">
            <path d="m21 21-4.34-4.34"/>
            <circle cx="11" cy="11" r="8"/>
          </svg>
        </span>
        <input id={id} placeholder="Search name or symbol" aria-label="Search name or symbol" className="art:peer art:h-full art:w-full art:bg-transparent art:text-sm art:leading-6 art:text-foreground art:caret-foreground art:outline-none art:placeholder:text-muted-foreground/60 art:pl-10 art:pr-3.5" value={value} onChange={(event) => onChange(event.target.value)} onFocus={() => setFocused(true)} onBlur={() => setFocused(false)}/>
      </div>
      <div className="art:contents"/>
    </div>);
}
function CategoryTabs({ value, onChange, watchCount, }: {
    value: TabValue;
    onChange: (value: TabValue) => void;
    watchCount: number;
}) {
    const id = useId();
    const refs = useRef<(HTMLButtonElement | null)[]>([]);
    const onKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
        if (event.key !== "ArrowRight" && event.key !== "ArrowLeft")
            return;
        event.preventDefault();
        const current = TABS.findIndex((tab) => tab.value === value);
        const next = (current + (event.key === "ArrowRight" ? 1 : -1) + TABS.length) % TABS.length;
        onChange(TABS[next].value);
        refs.current[next]?.focus();
    };
    return (<div role="tablist" className="art:items-center art:gap-1 art:rounded-full art:bg-muted art:p-1 art:flex art:max-w-full art:overflow-x-auto art:[scrollbar-width:none] art:@min-[640px]/artemis:inline-flex" aria-label="Market categories" onKeyDown={onKeyDown}>
      {TABS.map((tab, index) => {
            const active = tab.value === value;
            return (<div key={tab.value} className="art:relative">
            {active ? (<motion.span layoutId={`${id}-indicator`} layout="position" className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }} transition={TAB_INDICATOR}/>) : null}
            <button ref={(node) => {
                    refs.current[index] = node;
                }} type="button" role="tab" aria-selected={active} className={artemisCx(TAB_BUTTON, active ? "art:text-foreground art:delay-100" : "art:text-muted-foreground art:delay-0 art:hover:text-foreground", "art:rounded-full art:h-8 art:px-3 art:text-xs")} id={`${id}-tab-${tab.value === "layer1" ? "layer1" : tab.value}`} tabIndex={active ? 0 : -1} onClick={() => onChange(tab.value)}>
              {tab.value === "watchlist" ? `${tab.label} ${watchCount}` : tab.label}
            </button>
          </div>);
        })}
    </div>);
}
function Row({ coin, index, entering, watched, onToggle, }: {
    coin: LiveCoin;
    index: number;
    entering: boolean;
    watched: boolean;
    onToggle: (symbol: string) => void;
}) {
    const delay = entering ? index * ROW_STAGGER : 0;
    return (<motion.tr layout="position" className="art:group art:border-b art:border-border art:last:border-b-0" initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, transition: ROW_EXIT }} transition={{ opacity: { ...ROW_IN, delay }, y: { ...ROW_IN, delay }, layout: ROW_LAYOUT }}>
      <td className="art:w-10 art:py-3 art:pr-1 art:pl-2">
        <button type="button" className={STAR_BUTTON} aria-pressed={watched} aria-label={watched ? `Remove ${coin.name} from watchlist` : `Add ${coin.name} to watchlist`} tabIndex={0} onClick={() => onToggle(coin.symbol)}>
          <motion.span key={watched ? "on" : "off"} className={artemisCx("art:flex", watched ? "art:text-amber-500" : "art:text-muted-foreground")} initial={watched ? { scale: 0.4, rotate: -30 } : false} animate={{ scale: 1, rotate: 0 }} transition={STAR_SPRING}>
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill={watched ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-star art:size-4" aria-hidden="true">
              <path d={STAR_PATH}/>
            </svg>
          </motion.span>
        </button>
      </td>
      <td className="art:hidden art:w-10 art:py-3 art:text-sm art:text-muted-foreground art:tabular-nums art:@min-[640px]/artemis:table-cell">{coin.rank}</td>
      <th scope="row" className="art:py-3 art:pr-3 art:text-left art:font-normal">
        <div className="art:relative art:flex art:min-w-0 art:items-center art:gap-3">
          <CoinMark symbol={coin.symbol} size="art:size-8"/>
          <div className="art:min-w-0">
            <span className="art:block art:truncate art:text-sm art:font-medium">{coin.name}</span>
            <span className="art:block art:text-xs art:text-muted-foreground">{coin.symbol}</span>
          </div>
        </div>
      </th>
      <td className="art:py-3 art:pr-3 art:text-right">
        <span className="art:relative art:inline-flex art:rounded-lg art:px-1.5 art:py-0.5 art:text-sm art:font-medium art:tabular-nums">
          {coin.direction ? (<motion.span key={coin.flash} aria-hidden="true" className={artemisCx("art:absolute art:inset-0 art:rounded-lg", coin.direction === "up" ? "art:bg-emerald-500/15" : "art:bg-red-500/15")} initial={{ opacity: 1 }} animate={{ opacity: 0 }} transition={FLASH}/>) : null}
          <ArtemisDigitSwap value={formatPrice(coin.price)} direction={coin.direction ?? "up"} className="art:relative"/>
        </span>
        <span className={artemisCx("art:block art:pr-1.5 art:text-xs art:tabular-nums art:@min-[768px]/artemis:hidden", changeColor(coin.change))}>
          {formatChange(coin.change)}
        </span>
      </td>
      <td className={artemisCx("art:hidden art:py-3 art:pr-3 art:text-right art:text-sm art:tabular-nums art:@min-[768px]/artemis:table-cell", changeColor(coin.change))}>
        <ArtemisDigitSwap value={formatChange(coin.change)}/>
      </td>
      <td className="art:hidden art:py-3 art:pr-3 art:@min-[1024px]/artemis:table-cell">
        {coin.spark ? (<svg viewBox="0 0 64 24" className="art:shrink-0 art:overflow-visible art:ml-auto art:h-8 art:w-28" aria-hidden="true">
            <motion.polyline points={coin.spark.points} pathLength="1" fill="none" strokeWidth="1.75" strokeLinecap="round" strokeLinejoin="round" strokeDasharray="1 1" className={coin.spark.stroke} initial={{ strokeDashoffset: 1 }} animate={{ strokeDashoffset: 0 }} transition={{ ...SPARK, delay: SPARK_DELAY + delay }}/>
          </svg>) : (<span aria-hidden="true" className="art:ml-auto art:block art:h-px art:w-28 art:bg-muted-foreground/40"/>)}
      </td>
      <td className="art:hidden art:py-3 art:pr-3 art:text-right art:text-sm art:tabular-nums art:@min-[768px]/artemis:table-cell">{formatCompact(coin.cap)}</td>
      <td className="art:hidden art:py-3 art:pr-2 art:text-right art:text-sm art:text-muted-foreground art:tabular-nums art:@min-[1280px]/artemis:table-cell">
        {formatCompact(coin.volume)}
      </td>
    </motion.tr>);
}
export default function CryptoMarketsPriceTable() {
    const [coins, setCoins] = useState<LiveCoin[]>(() => COINS.map((coin) => ({ ...coin, direction: null, flash: 0 })));
    const coinsRef = useRef(coins);
    const [watchlist, setWatchlist] = useState<readonly string[]>(INITIAL_WATCHLIST);
    const [tab, setTab] = useState<TabValue>("all");
    const [query, setQuery] = useState("");
    const [sort, setSort] = useState<Sort>({ key: "rank", dir: "ascending" });
    const [entering, setEntering] = useState(true);
    const sectionRef = useRef<HTMLElement>(null);
    const inView = useInView(sectionRef, { amount: 0.1 });
    const stepRef = useRef(0);
    useEffect(() => {
        if (!inView)
            return;
        const timer = window.setInterval(() => {
            stepRef.current += 1;
            const next = tick(coinsRef.current, stepRef.current);
            coinsRef.current = next;
            setCoins(next);
        }, TICK_MS);
        return () => window.clearInterval(timer);
    }, [inView]);
    useEffect(() => {
        const timer = window.setTimeout(() => setEntering(false), 1000);
        return () => window.clearTimeout(timer);
    }, []);
    const totalCap = coins.reduce((sum, coin) => sum + coin.cap, 0);
    const totalVolume = coins.reduce((sum, coin) => sum + coin.volume, 0);
    const topGainer = coins.reduce((best, coin) => (coin.change > best.change ? coin : best), coins[0]);
    const rows = useMemo(() => {
        const needle = query.trim().toLowerCase();
        const filtered = coins.filter((coin) => {
            if (tab === "watchlist" && !watchlist.includes(coin.symbol))
                return false;
            if (tab !== "all" && tab !== "watchlist" && !coin.categories.includes(tab))
                return false;
            if (!needle)
                return true;
            return coin.name.toLowerCase().includes(needle) || coin.symbol.toLowerCase().includes(needle);
        });
        const sign = sort.dir === "ascending" ? 1 : -1;
        return filtered.sort((a, b) => sign * compare(a, b, sort.key) || a.rank - b.rank);
    }, [coins, tab, watchlist, query, sort]);
    const onSort = (key: SortKey) => setSort((current) => current.key === key
        ? { key, dir: current.dir === "ascending" ? "descending" : "ascending" }
        : { key, dir: key === "name" || key === "rank" ? "ascending" : "descending" });
    const onToggle = (symbol: string) => setWatchlist((current) => (current.includes(symbol) ? current.filter((s) => s !== symbol) : [...current, symbol]));
    const emptyMessage = query.trim() ? "No coins match your search." : tab === "watchlist" ? "Star a coin to keep it here." : "No coins match your search.";
    return (<>
      <section ref={sectionRef} aria-label="Markets" className="art:w-full art:bg-background art:px-4 art:py-12 art:text-foreground art:@min-[640px]/artemis:px-8 art:@min-[640px]/artemis:py-16">
        <div className="art:mx-auto art:max-w-5xl">
          <div className="art:flex art:flex-wrap art:items-center art:justify-between art:gap-4">
            <div className="art:flex art:items-center art:gap-3">
              <h2 className="art:text-xl art:font-medium">Markets</h2>
              <span className="art:rounded-full art:bg-muted art:px-2.5 art:py-0.5 art:text-xs art:text-muted-foreground">Live</span>
            </div>
            <SearchField value={query} onChange={setQuery}/>
          </div>
          <div className="art:mt-6">
            <dl className="art:grid art:divide-y art:divide-border art:rounded-3xl art:border art:border-border art:bg-background art:@min-[640px]/artemis:grid-cols-3 art:@min-[640px]/artemis:divide-x art:@min-[640px]/artemis:divide-y-0">
              <div className="art:px-5 art:py-4">
                <dt className="art:text-xs art:text-muted-foreground">Total market cap</dt>
                <dd className="art:mt-1.5 art:text-2xl art:font-medium art:tracking-tight art:tabular-nums">
                  <ArtemisDigitSwap value={formatCompact(totalCap)}/>
                </dd>
              </div>
              <div className="art:px-5 art:py-4">
                <dt className="art:text-xs art:text-muted-foreground">24h volume</dt>
                <dd className="art:mt-1.5 art:text-2xl art:font-medium art:tracking-tight art:tabular-nums">
                  <ArtemisDigitSwap value={formatCompact(totalVolume)}/>
                </dd>
              </div>
              <div className="art:px-5 art:py-4">
                <dt className="art:text-xs art:text-muted-foreground">Top gainer</dt>
                <dd className="art:mt-1.5 art:flex art:items-center art:gap-2 art:text-2xl art:font-medium art:tracking-tight">
                  <CoinMark symbol={topGainer.symbol} size="art:size-7"/>
                  {topGainer.symbol}
                  <span className={artemisCx("art:text-base art:tabular-nums", positive(topGainer.change) ? "art:text-emerald-600 art:dark:text-emerald-400" : "art:text-red-600 art:dark:text-red-400")}>
                    <ArtemisDigitSwap value={formatChange(topGainer.change)}/>
                  </span>
                </dd>
              </div>
            </dl>
          </div>
          <div className="art:mt-6">
            <CategoryTabs value={tab} onChange={setTab} watchCount={watchlist.length}/>
          </div>
          <div className="art:mt-4">
            <div className="art:overflow-clip art:rounded-3xl art:border art:border-border art:bg-background">
              <table className="art:w-full art:border-collapse">
                <thead>
                  <tr className="art:border-b art:border-border">
                    <th scope="col" className="art:py-3 art:text-xs art:font-normal art:text-muted-foreground art:pr-1 art:pl-2 art:w-10"/>
                    <SortHeader label="#" sortKey="rank" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:hidden art:w-10 art:@min-[640px]/artemis:table-cell"/>
                    <SortHeader label="Name" sortKey="name" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:text-left"/>
                    <SortHeader label="Price" sortKey="price" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:w-32 art:text-right art:@min-[640px]/artemis:w-36"/>
                    <SortHeader label="24h" sortKey="change" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:hidden art:w-24 art:text-right art:@min-[768px]/artemis:table-cell"/>
                    <th scope="col" className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:hidden art:w-36 art:text-right art:@min-[1024px]/artemis:table-cell">
                      Last 7 days
                    </th>
                    <SortHeader label="Market cap" sortKey="cap" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:hidden art:w-28 art:text-right art:@min-[768px]/artemis:table-cell"/>
                    <SortHeader label="Volume (24h)" sortKey="volume" sort={sort} onSort={onSort} className="art:py-3 art:pr-3 art:text-xs art:font-normal art:text-muted-foreground art:hidden art:w-28 art:text-right art:@min-[1280px]/artemis:table-cell"/>
                  </tr>
                </thead>
                <tbody>
                  <AnimatePresence initial>
                    {rows.map((coin, index) => (<Row key={coin.symbol} coin={coin} index={index} entering={entering} watched={watchlist.includes(coin.symbol)} onToggle={onToggle}/>))}
                  </AnimatePresence>
                </tbody>
              </table>
              {rows.length === 0 ? <p className="art:px-6 art:py-14 art:text-center art:text-sm art:text-muted-foreground">{emptyMessage}</p> : null}
            </div>
          </div>
          <p className="art:mt-4 art:text-xs art:text-muted-foreground">
            {"Sample prices"}
            {" with a simulated live feed"}
            {". Not market data."}
          </p>
        </div>
      </section>
    </>);
}

// @zeus-internal
import type { ReactElement } from "react";
const symbols = ["BTC","ETH","USDT","BNB","SOL","USDC","XRP","DOGE","TON","ADA","AVAX","LINK","DAI","UNI","PEPE","POL","ARB","AAVE","OP"];
const colors = ["#ed8b21","#7279dd","#009b87","#e9ba34","#7c53ca","#3277c6","#d75883","#4ba3bc"];
export const COIN_ICONS: Record<string, ReactElement> = Object.fromEntries(symbols.map((symbol, index) => [symbol, <svg key={symbol} viewBox="0 0 24 24" className="art:size-full" aria-hidden="true"><circle cx="12" cy="12" r="12" fill={colors[index % colors.length]}/><path d={index % 3 === 0 ? "M12 5 18 12 12 19 6 12Z" : index % 3 === 1 ? "M7 8h10v8H7zM12 5v14" : "M6 12h12M12 6v12"} fill="none" stroke="white" strokeWidth="1.7" strokeLinejoin="round"/></svg>]));
